import {placeCampSeatControls} from './control-clearance.js';
import {CAMP_CHAIRS} from './tent-layout.js';
import {posePlazaVisitor as poseVisitor} from './visitor-view.js';
import {PLAZA,plazaCollision} from './layout.js';import {PlazaSession} from './model.js';import {PlazaGuests} from './guests.js';import {buildPlazaEffects} from './effects.js';import {createCampfireAudio} from './crackle-audio.js';import {createPlazaCamera} from './camera.js';import {createPhotoCompanion} from '../village/photo-cast.js';import {disposeToyTree} from '../world/toy-kit.js';import {ROOMS} from '../world/rooms.js';
export const PLAZA_BODY=`<div class="plaza-heading"><strong>해변 캠핑 · 불꽃놀이</strong><button data-plaza-close aria-label="모닥불 조작 닫기">닫기 ×</button></div><p class="plaza-description">파도와 따뜻한 불 옆에서 천천히 쉬어요</p><div class="plaza-actions"><button data-plaza-fire>모닥불 켜기</button><button data-plaza-marshmallow>마시멜로 굽기</button><button data-plaza-sit>옆에 앉기</button><button data-plaza-show>불꽃놀이 시작</button></div><div class="plaza-audio"><button data-plaza-mute aria-pressed="false">파도 · 타닥타닥 소리 끄기</button><label>소리 크기 <input data-plaza-volume type="range" min="0" max="100" value="32" aria-label="캠핑과 불꽃놀이 소리 크기"></label></div><p data-plaza-status class="plaza-status" aria-live="polite"></p>`;
export function createPlazaController({stage,getRoom,getView,getActors,getActivity=()=>null,getShowSource=()=>null,getCamera,getReturnViewport=()=>null,getEffectsViewport=()=>null,gameAudio,reduced=false,getQuality=()=> 'high',onBusy=()=>{},onSit=()=>{},onMarshmallow=()=>{},ui={toast(){}},doc=globalThis.document,win=globalThis.window,loadVisitor=createPhotoCompanion,disposeVisitor=disposeToyTree}={}){
 let alive=true,current=null,panel=null,token=0,lastBusy=false,previousFocus=null,blurred=false,controlsPaused=false,viewCover=null;const sound=createCampfireAudio({unlock:()=>gameAudio?.unlock(),onState:()=>render()});
 const isSeated=()=>{const current=getActivity();return current?.state==='active'&&[...PLAZA.seats,...CAMP_CHAIRS].some(a=>a.id===current.activity?.id);};
 const sameShowSeat=source=>{const a=getActivity();return !!source&&a?.state==='active'&&a.activity?.id===source.activityId&&getRoom()==='courtyard';};
 const isBusy=()=>!!current?.camera?.active;
 function busyChanged(){const busy=isBusy();if(busy!==lastBusy){lastBusy=busy;onBusy(busy);if(!busy&&current?.showSource){const source=current.showSource;current.showSource=null;try{if(sameShowSeat(source))source.resumeFrom?.(current.camera.camera);}finally{source.dispose?.();}}render();}}
 function syncCover(){const camera=current?.camera;if(!camera?.active||!camera.covered){viewCover?.remove();viewCover=null;return;}if(!viewCover){viewCover=doc.createElement('div');viewCover.className='plaza-view-cover';viewCover.setAttribute('aria-hidden','true');if(stage.prepend)stage.prepend(viewCover);else stage.appendChild(viewCover);}viewCover.style.opacity=String(camera.coverOpacity);viewCover.dataset.context=camera.context;}
 function render(){if(!panel||!current)return;const state=current.session.snapshot(),audio=sound.snapshot(),busy=isBusy(),seated=isSeated();panel.dataset.mode=busy?'show':seated?'seat':'controls';for(const selector of ['.plaza-heading','.plaza-description','[data-plaza-marshmallow]','[data-plaza-sit]'])panel.querySelector(selector).hidden=busy||seated;panel.querySelector('.plaza-audio label').hidden=seated&&!busy;panel.querySelector('[data-plaza-fire]').hidden=busy;panel.querySelector('.plaza-status').hidden=(busy||seated)&&!audio.error;panel.querySelector('[data-plaza-volume]').value=String(Math.round(audio.volume*100));panel.querySelector('[data-plaza-fire]').textContent=state.burning?'모닥불 끄기':'모닥불 켜기';panel.querySelector('[data-plaza-show]').disabled=false;panel.querySelector('[data-plaza-show]').textContent=isBusy()?'불꽃놀이 멈추기':'불꽃놀이 시작';panel.querySelector('[data-plaza-sit]').disabled=isBusy()||current.guests.playerSeat;panel.querySelector('[data-plaza-sit]').textContent=current.guests.playerSeat?'앉아 있어요':'옆에 앉기';const mute=panel.querySelector('[data-plaza-mute]');mute.textContent=(busy||seated)?(audio.muted?'소리 켜기':'소리 끄기'):(audio.muted?'파도 · 타닥타닥 소리 켜기':'파도 · 타닥타닥 소리 끄기');mute.setAttribute('aria-pressed',String(audio.muted));panel.querySelector('[data-plaza-status]').textContent=audio.error|| (reduced?'느린 불꽃 · 움직임을 줄여서 보여줘요':state.fireworks?'바다 위로 피어나는 큰 불꽃 · 24초':'소리 크기는 배경음악과 따로 조절해요');placeCampSeatControls(panel,stage,doc);}
 function closePanel(){if(!panel)return;panel.remove();panel=null;if(previousFocus?.isConnected!==false)previousFocus?.focus?.();previousFocus=null;}
 function cleanup(){token++;sound.updateFireworks(null);closePanel();viewCover?.remove();viewCover=null;if(!current)return;current.showSource?.dispose?.();current.showSource=null;current.session.dispose();current.guests.dispose();current.camera?.dispose();for(const model of current.models.values())disposeVisitor(model);current.effects.dispose();current=null;sound.setBurning(false);busyChanged();}
 function ensure(){if(!alive)return false;const view=getView?.();if(getRoom?.()!=='courtyard'||!view?.root){cleanup();return false;}if(current?.view===view)return true;cleanup();const session=new PlazaSession(),guests=new PlazaGuests(plazaCollision(ROOMS.courtyard)),effects=buildPlazaEffects(view.root),models=new Map();current={view,session,guests,effects,models,camera:null};return true;}
 async function addVisitors(){if(!current||current.loading)return;current.loading=true;const instance=current,request=token;await Promise.all(PLAZA.visitors.map(async spec=>{try{if(instance.models.has(spec.id))return;const model=await loadVisitor(spec.id);if(!alive||current!==instance||request!==token){disposeVisitor(model);return;}model.visible=false;instance.models.set(spec.id,model);instance.view.root.add(model);const r=instance.guests.snapshot().find(r=>r.id===spec.id);poseVisitor(model,r,true);}catch{if(alive&&current===instance)ui.toast?.('친구가 오는 길이 조금 늦어요. 모닥불은 계속 즐길 수 있어요');}}));if(alive&&current===instance)instance.loading=false;}
 async function toggleFire(){if(!ensure())return false;const burning=current.session.toggleFire();current.guests.setGathering(burning);sound.setBurning(burning);if(burning){void addVisitors();await sound.enable();}render();return burning;}
 function startFireworks(){if(!ensure()||isBusy())return false;if(!sound.snapshot().muted)void sound.enable();let source=null;try{source=getShowSource();current.showSource=source;current.camera=createPlazaCamera(source?.camera??getCamera(),{reduced,forceCovered:!!source?.forceCovered,getReturnViewport:source?()=>sameShowSeat(source)?source.getReturnViewport():getReturnViewport():getReturnViewport,getReturnCamera:source?(w,h)=>sameShowSeat(source)?source.getReturnCamera(w,h):getCamera():undefined});current.camera.enter(stage.clientWidth||390,stage.clientHeight||600);current.pendingFireworks=true;}catch{source?.abort?.();source?.dispose?.();current.showSource=null;current.pendingFireworks=false;current.camera?.dispose();current.camera=null;current.session.stopFireworks();return false;}busyChanged();syncCover();render();return true;}

 function stopFireworks(){if(!current)return;sound.updateFireworks(null);current.pendingFireworks=false;current.session.stopFireworks();current.camera?.exit();syncCover();render();}
 function openPanel(focus=true){if(!ensure()||panel)return false;previousFocus=focus?doc.activeElement:null;panel=doc.createElement('section');panel.className='plaza-panel';panel.setAttribute('aria-label','모닥불과 불꽃놀이 조작');panel.innerHTML=PLAZA_BODY;stage.appendChild(panel);const mounted=panel,guard=fn=>(...args)=>{if(alive&&!controlsPaused&&panel===mounted&&current) return fn(...args);};panel.querySelector('[data-plaza-close]').onclick=guard(closePanel);panel.querySelector('[data-plaza-marshmallow]').onclick=guard(()=>{if(!isBusy())onMarshmallow();});panel.querySelector('[data-plaza-fire]').onclick=guard(()=>void toggleFire());panel.querySelector('[data-plaza-show]').onclick=guard(()=>isBusy()?stopFireworks():startFireworks());panel.querySelector('[data-plaza-sit]').onclick=guard(()=>{if(isBusy())return;closePanel();onSit(PLAZA.seats[0]);});panel.querySelector('[data-plaza-mute]').onclick=guard(()=>{sound.setMuted(!sound.snapshot().muted);if(!sound.snapshot().muted)void sound.enable();render();});panel.querySelector('[data-plaza-volume]').oninput=guard(e=>sound.setVolume(Number(e.target.value)/100));render();if(focus)panel.querySelector('[data-plaza-fire]').focus();return true;}
 function syncSeatedPanel(paused){controlsPaused=!!paused;const seated=isSeated();if(seated&&!paused&&!panel)openPanel(false);if(!panel)return;if(!seated&&panel.dataset.mode==='seat'&&!isBusy()){closePanel();return;}panel.hidden=!!paused;render();}
 function hidden(){sound.setHidden(!!doc.hidden||blurred);}
 function blur(){blurred=true;sound.setHidden(true);}
 function focus(){blurred=false;sound.setHidden(!!doc.hidden);}
 doc?.addEventListener?.('visibilitychange',hidden);win?.addEventListener?.('blur',blur);win?.addEventListener?.('focus',focus);
 return {get busy(){return isBusy();},get camera(){return isBusy()?current.camera.camera:null;},toggleFire,startFireworks,stopFireworks,open:openPanel,close:closePanel,claimSeat(id){const claimed=current?.guests.claimPlayerSeat(id)??false;render();return claimed;},releaseSeat(){current?.guests.releasePlayerSeat();render();},collisionCircles:()=>current?current.guests.snapshot().filter(r=>current.models.get(r.id)?.visible).map(r=>({x:r.x,z:r.z,radius:PLAZA.visitors.find(v=>v.id===r.id).radius})):[],tick(dt,{paused=false}={}){paused=paused||!!doc.hidden||blurred;if(paused&&!current)return;if(!ensure())return;const state=current.session.snapshot(),player=getActors?.().player?.position??{x:0,z:0};current.session.tick(dt,{paused});const activeIds=new Set(),guests=current.guests.snapshot();for(const r of guests){const model=current.models.get(r.id),radius=PLAZA.visitors.find(v=>v.id===r.id).radius;if(!model)continue;const clear=Math.hypot(r.x-player.x,r.z-player.z)>=radius+.66+.065&&guests.every(other=>other.id===r.id||!current.models.get(other.id)?.visible||Math.hypot(r.x-other.x,r.z-other.z)>=radius+PLAZA.visitors.find(v=>v.id===other.id).radius+.08);if(model.visible||(state.burning&&!paused&&!current.loading&&clear)){model.visible=true;activeIds.add(r.id);}}current.guests.tick(dt,player,{paused:paused||!!current.loading,activeIds});for(const r of current.guests.snapshot()){const model=current.models.get(r.id);if(model){model.visible=activeIds.has(r.id)&&(current.session.burning||r.phase!=='idle');poseVisitor(model,r,reduced);}}let next=current.session.snapshot();if(state.fireworks&&!next.fireworks)current.camera?.exit();current.camera?.tick(paused?0:dt);if(current.pendingFireworks&&!paused&&current.camera?.phase==='active'){current.pendingFireworks=false;current.session.startFireworks();next=current.session.snapshot();}syncCover();current.effects.updateTent(player,paused?0:dt,{reduced});const effectView=getEffectsViewport();current.effects.update({...next,showPreparing:!!current.pendingFireworks,showSkyReady:!!current.pendingFireworks&&!!current.camera?.covered&&current.camera.context==='show'},{quality:getQuality(),reduced,dpr:globalThis.devicePixelRatio||1,camera:current.camera?.active?current.camera.camera:effectView?.camera??getCamera(),viewportHeight:current.camera?.active?(stage.clientHeight||600):(effectView?.height??stage.clientHeight??600)});sound.setHidden(!!doc.hidden||blurred||paused);sound.updateFireworks(next.fireworks,{reduced});sound.setDistance(Math.hypot(player.x-PLAZA.fire.x,player.z-PLAZA.fire.z));sound.tick(paused?0:dt);if(panel&&!isBusy()&&!isSeated()&&Math.hypot(player.x-PLAZA.fire.x,player.z-PLAZA.fire.z)>5)closePanel();busyChanged();syncSeatedPanel(paused);if(state.fireworks&&!next.fireworks)render();},fit(w,h){current?.camera?.fit(w,h);syncCover();},render(scene,draw){const camera=current?.camera;if(camera?.active&&sameShowSeat(current.showSource)&&(current.showSource.keepDuringShow||camera.context==='source'))return current.showSource.render(scene,camera.camera,draw);return draw(camera?.active?camera.camera:getCamera());},snapshot:()=>current?{...current.session.snapshot(),guests:current.guests.snapshot(),audio:sound.snapshot(),busy:isBusy(),panel:!!panel,seatControls:!!panel&&isSeated(),pendingFireworks:!!current.pendingFireworks,showCameraPhase:current.camera?.phase??null,showContext:current.camera?.context??null,coverOpacity:current.camera?.coverOpacity??0}:null,cancel(){cleanup();},dispose(){if(!alive)return;alive=false;cleanup();sound.dispose();doc?.removeEventListener?.('visibilitychange',hidden);win?.removeEventListener?.('blur',blur);win?.removeEventListener?.('focus',focus);}};
}
